/* Lexical analyzer main function */
int yylex() {
    if (!yy_cp || !*yy_cp) return YY_NULL;

    int current_state = START_STATE;
    char* yy_last_accepting_char_ptr = nullptr;
    int yy_last_accepting_state = -1;
    char* yy_start_ptr = yy_cp;

    while (true) {
        char c = *yy_cp;
        int col = yy_edge_col[(unsigned char)c];

        if (col == 0) {
            // Character not in alphabet
            if (yy_last_accepting_state != -1) {
                // Backtrack to last accepting state
                yy_cp = yy_last_accepting_char_ptr;
                char yy_saved = *yy_cp;
                *yy_cp = '\0';
                yytext = std::string(yy_start_ptr);
                yy_leng = yytext.length();
                int action_idx = yy_accept[yy_last_accepting_state] - 1;
                *yy_cp = yy_saved;  // Restore original character
                yy_last_accepting_state = -1;
                yy_start_ptr = yy_cp;
                int result = find_action(action_idx, yytext.c_str(), yy_leng);
                if (result != -1) return result;
                current_state = START_STATE;  // Reset state for continue
                continue;  // Continue scanning for rules without return
            } else {
                // No accepting state - skip character
                yy_cp++;
                // Update position tracking for skipped character
                if (c == '\n') {
                    yy_line_num++;
                    yy_col_num = 1;
                } else {
                    yy_col_num++;
                }
                // Check if we've reached end of input
                if (*yy_cp == '\0') {
                    return YY_NULL;
                }
                yy_start_ptr = yy_cp;
                current_state = START_STATE;
                continue;
            }
        }

        int next_state = yy_next[yy_state_row[current_state] + col];

        if (next_state == -1) {
            // No transition - check for accepting state
            if (yy_last_accepting_state != -1) {
                // Backtrack to last accepting state
                yy_cp = yy_last_accepting_char_ptr;
                char yy_saved = *yy_cp;
                *yy_cp = '\0';
                yytext = std::string(yy_start_ptr);
                yy_leng = yytext.length();
                int action_idx = yy_accept[yy_last_accepting_state] - 1;
                *yy_cp = yy_saved;  // Restore original character
                yy_last_accepting_state = -1;
                yy_start_ptr = yy_cp;
                int result = find_action(action_idx, yytext.c_str(), yy_leng);
                if (result != -1) return result;
                current_state = START_STATE;  // Reset state for continue
                continue;  // Continue scanning for rules without return
            } else {
                // No accepting state - skip character
                yy_cp++;
                // Update position tracking for skipped character
                if (c == '\n') {
                    yy_line_num++;
                    yy_col_num = 1;
                } else {
                    yy_col_num++;
                }
                // Check if we've reached end of input
                if (*yy_cp == '\0') {
                    return YY_NULL;
                }
                yy_start_ptr = yy_cp;
                current_state = START_STATE;
                continue;
            }
        }

        // Check if current state is accepting
        if (yy_accept[next_state] != 0) {
            yy_last_accepting_state = next_state;
            yy_last_accepting_char_ptr = yy_cp + 1;
        }

        // Update position tracking
        if (c == '\n') {
            yy_line_num++;
            yy_col_num = 1;
        } else {
            yy_col_num++;
        }

        yy_cp++;
        current_state = next_state;

        // Check for end of input
        if (*yy_cp == '\0') {
            if (yy_last_accepting_state != -1) {
                yytext = std::string(yy_start_ptr);
                yy_leng = yytext.length();
                int action_idx = yy_accept[yy_last_accepting_state] - 1;
                yy_last_accepting_state = -1;
                yy_start_ptr = yy_cp;
                int result = find_action(action_idx, yytext.c_str(), yy_leng);
                if (result != -1) return result;
                return YY_NULL;  // Continue would cause infinite loop at EOF
            }
            return YY_NULL;
        }
    }
}

/* Initialize lexer with input file */
void yy_init(const char* filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error: Cannot open file " << filename << std::endl;
        return;
    }

    file.seekg(0, std::ios::end);
    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);

    yy_file_buffer = new char[size + 2];
    file.read(yy_file_buffer, size);
    yy_file_buffer[size] = '\0';
    yy_file_buffer[size + 1] = '\0';

    yy_cp = yy_file_buffer;
    yy_line_num = 1;
    yy_col_num = 1;
}

/* Cleanup lexer resources */
void yy_cleanup() {
    if (yy_file_buffer) {
        delete[] yy_file_buffer;
        yy_file_buffer = nullptr;
    }
    yy_cp = nullptr;
}

/* Read next character from input */
int input(void) {
    if (!yy_cp || !*yy_cp) return 0;
    return *yy_cp++;
}

/* Put back character to input */
void unput(int c) {
    if (yy_cp > yy_file_buffer) {
        *(--yy_cp) = c;
    }
}

